// ---- clipboard limits and chunks ----

const B64 = /^[A-Za-z0-9+/]*={0,2}$/

function isBase64(s: string): boolean {
	return s.length % 4 === 0 && B64.test(s)
}

function base64Encode(bytes: Uint8Array): string {
	let s = ''
	for (let i = 0; i < bytes.length; i += 0x8000) {
		s += String.fromCharCode(...bytes.subarray(i, i + 0x8000))
	}
	return btoa(s)
}

function base64Decode(s: string): Uint8Array {
	if (!isBase64(s)) throw new StreamFrameError('not base64')
	const bin = atob(s)
	const out = new Uint8Array(bin.length)
	for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i)
	return out
}

function base64Length(s: string): number {
	return (s.length / 4) * 3 - (s.endsWith('==') ? 2 : s.endsWith('=') ? 1 : 0)
}

/**
 * Checks a clip's limits: at most one item per type, text at most 1 MiB of
 * UTF-8, a PNG at most 8 MiB decoded and valid base64. Returns the error
 * code to answer, or null.
 */
export function checkClip(clip: Clip): ErrorCode | null {
	const seen = new Set<string>()
	for (const item of clip.items) {
		if (seen.has(item.mime)) return 'invalid_message'
		seen.add(item.mime)
		if (item.mime === 'text/plain') {
			if (new TextEncoder().encode(item.data).length > MAX_CLIP_TEXT_BYTES) return 'too_large'
		} else {
			// Refuse on length before reading anything large.
			if (item.data.length > (Math.floor(MAX_CLIP_IMAGE_BYTES / 3) + 1) * 4) return 'too_large'
			if (!isBase64(item.data)) return 'invalid_message'
			if (base64Length(item.data) > MAX_CLIP_IMAGE_BYTES) return 'too_large'
		}
	}
	return null
}

/** The `clip` frame's UTF-8 cut into `clip_chunk` frames of at most `sliceBytes`. */
export function chunkClip(clip: Clip, sliceBytes: number = CHUNK_SLICE_BYTES): ClipChunk[] {
	const bytes = new TextEncoder().encode(
		JSON.stringify({ t: 'clip', seq: clip.seq, items: clip.items }),
	)
	const n = Math.max(1, Math.ceil(bytes.length / sliceBytes))
	return Array.from({ length: n }, (_, i) => ({
		t: 'clip_chunk' as const,
		seq: clip.seq,
		i,
		n,
		data: base64Encode(bytes.subarray(i * sliceBytes, (i + 1) * sliceBytes)),
	}))
}

/** The frames that carry a clip: itself when its JSON is at most 16 KiB, else its chunks. */
export function clipFrames(clip: Clip): Clipboard[] {
	const json = JSON.stringify({ t: 'clip', seq: clip.seq, items: clip.items })
	return new TextEncoder().encode(json).length <= MAX_FRAME_BYTES
		? [{ t: 'clip', seq: clip.seq, items: clip.items }]
		: chunkClip(clip)
}

/** Joins `clip_chunk` frames; a chunk of another `seq` drops an unfinished clip. */
export class ChunkJoiner {
	private seq: number | null = null
	private parts: (Uint8Array | undefined)[] = []

	/** Adds one chunk; returns the clip once every slice has arrived. Throws on a bad chunk. */
	push(c: ClipChunk): Clip | null {
		if (c.n === 0 || c.n > MAX_CHUNKS || c.i >= c.n) throw new StreamFrameError('bad chunk index')
		if (this.seq !== c.seq || this.parts.length !== c.n) {
			this.seq = c.seq
			this.parts = new Array(c.n).fill(undefined)
		}
		const bytes = base64Decode(c.data)
		if (bytes.length > CHUNK_SLICE_BYTES) throw new StreamFrameError('chunk too large', 'too_large')
		this.parts[c.i] = bytes
		if (this.parts.some((p) => p === undefined)) return null
		const total = this.parts.reduce((a, p) => a + p!.length, 0)
		const joined = new Uint8Array(total)
		let o = 0
		for (const p of this.parts) {
			joined.set(p!, o)
			o += p!.length
		}
		this.seq = null
		this.parts = []
		let text: string
		try {
			text = new TextDecoder('utf-8', { fatal: true }).decode(joined)
		} catch {
			throw new StreamFrameError('chunks are not UTF-8')
		}
		const frame = parseFrame('clipboard', text)
		if (frame.t !== 'clip') throw new StreamFrameError('chunks are not a clip')
		return frame
	}
}
